 p=argparse.ArgumentParser();p.add_argument('--log',type=Path,required=True);p.add_argument('--result',type=Path,required=True);p.add_argument('--expected-manifest-sha256',required=True);a=p.parse_args();t=a.log.read_text(encoding='utf-8',errors='replace');m=re.findall(r'M237_FIXED_TEXT_ACCEPTANCE_BEGIN\s*(\{.*?\})\s*M237_FIXED_TEXT_ACCEPTANCE_END',t,re.S)
